package com.wizzadrds.theworldremembers.voice; import org.junit.jupiter.api.Test;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*; class VoiceSchedulerTest{@Test void dangerPreemptsAmbient(){var s=new VoiceScheduler(1);var a=new VoiceJob(UUID.randomUUID(),"ambient",VoicePriority.AMBIENT,1);var d=new VoiceJob(UUID.randomUUID(),"danger",VoicePriority.DANGER,2);assertTrue(s.submit(a));assertTrue(s.submit(d));assertEquals(d,s.startNext());}@Test void sameNpcCannotOverlap(){var s=new VoiceScheduler(2);var id=UUID.randomUUID();assertTrue(s.submit(new VoiceJob(id,"a",VoicePriority.DIRECT,1)));assertEquals(id,s.startNext().npcId());assertFalse(s.submit(new VoiceJob(id,"b",VoicePriority.DIRECT,2)));}}
